function setMobile(tab){S.tab=tab;$('.workspace-content').dataset.mobile=tab;$('.mobile-work-tabs').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===(tab==='reader'?0:1)));S.editor?.requestMeasure();}
async function ensureTrust(){if(S.state.trusted)return true;const yes=await confirmBox('运行你信任的代码',S.platform==='windows'?'本版本的 Python 进程使用当前 Windows 账户权限，并非安全沙箱。代码可以访问该账户有权访问的文件。请只运行你自己编写或确认可信的程序。':'Python 在独立服务进程中运行，应用没有网络和外部存储权限。但代码仍能访问本应用的数据；独立进程不等于安全沙箱。请只运行可信程序。','我理解，运行代码');if(yes)await patchState({trusted:true});return yes;}
